use std::io::{self, Write};

fn main() {
    let mut board = [[false; 4]; 4];
    let mut current_player = 0; // 0 for X, 1 for O

    loop {
        print_board(&board);
        println!("Player {}'s turn", current_player + 1);
        let row = get_row();
        let col = get_column(&board, row);
        board[row][col] = true;

        if check_winner(&board, current_player) {
            println!("Player {} wins!", current_player + 1);
            break;
        }

        current_player = 1 - current_player;
    }
}

fn print_board(board: &[[bool; 4]; 4]) {
    for row in board {
        for &cell in row {
            print!("{}", if cell { 'O' } else { ' ' });
        }
        println!();
    }
    println!();
}

fn get_row() -> usize {
    let mut input = String::new();
    io::stdout().write(b"Enter row (0-3): ").unwrap();
    io::stdin().read_line(&mut input).unwrap();
    input.trim().parse().unwrap()
}

fn get_column(board: &[[bool; 4]; 4], row: usize) -> usize {
