}

fn check_winner(board: &[[bool; 4]; 4], player: usize) -> bool {
    // Check rows and columns
    for i in 0..4 {
        if board[i][i] && board[i][i] && board[i][i] && board[i][i] {
            return true;
        }
        if board[i][3 - i] && board[i][3 - i] && board[i][3 - i] && board[i][3 - i] {
            return true;
        }
    }

    // Check diagonals
    if board[0][0] && board[1][1] && board[2][2] && board[3][3] {
        return true;
    }
    if board[0][3] && board[1][2] && board[2][1] && board[3][0] {
        return true;
    }

    false
}
